parameters.jsCode:
// Split competitor list into individual items
const raw = $input.item.json.competitors;
let competitors;
try {
  competitors = JSON.parse(raw);
} catch(e) {
  competitors = [];
}
return competitors.map(c => ({ json: c }));

// Extract readable text — strip HTML tags and excess whitespace
const html = $input.item.json.data || $input.item.json || '';
const text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 3000); // Keep first 3000 chars for comparison

const competitor = $('Split Competitors').item.json;

return [{ json: {
  name: competitor.name,
  url: competitor.url,
  current_text: text,
  checked_date: new Date().toISOString().split('T')[0]
}}];

