parameters.jsCode:
const raw = $input.item.json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  parsed = { has_changes: false, change_summary: 'Parse error', change_type: 'none', significance: 'low' };
}

const pageData = $('Extract Page Text').item.json;
const airtableData = $('Get Last Snapshot').item.json;

return [{ json: {
  name: pageData.name,
  url: pageData.url,
  current_text: pageData.current_text,
  checked_date: pageData.checked_date,
  has_changes: parsed.has_changes,
  change_summary: parsed.change_summary,
  change_type: parsed.change_type,
  significance: parsed.significance,
  record_id: airtableData.records?.[0]?.id || null,
  is_new: !airtableData.records?.length
}}];

